  "widget.assumptions.ctrl.which.linearity": { en: "Linearity", es: "Linealidad" },
  "widget.assumptions.ctrl.which.meanzero": { en: "Mean-Zero", es: "Media cero" },
  "widget.assumptions.ctrl.which.none": { en: "All Correct", es: "Todo correcto" },
  "widget.assumptions.heading": { en: "OLS Assumptions Diagnostic", es: "Diagnóstico de supuestos de MCO" },
  "widget.assumptions.howto": { en: "<li><strong>Pick an assumption to violate</strong> — choose linearity, mean-zero, homoskedasticity, or independence to see its effect in isolation.</li>\n      <li><strong>Slide severity</strong> — turn the violation up from mild to extreme and watch the estimated slope drift or the scatter fan out.</li>\n      <li><strong>Click Resimulate</strong> — redraw the sample under the chosen violation and see how consistent the distortion is.</li>", es: "<li><strong>Elige un supuesto a violar</strong> — selecciona linealidad, media cero, homocedasticidad o independencia para ver su efecto de forma aislada.</li>\n      <li><strong>Desliza la severidad</strong> — sube la violación de leve a extrema y observa cómo deriva la pendiente estimada o cómo se abre la nube.</li>\n      <li><strong>Haz clic en Resimular</strong> — vuelve a extraer la muestra bajo la violación elegida y observa qué tan consistente es la distorsión.</li>" },
  "widget.assumptions.kc": { en: "<span class=\"kc-title\">Four assumptions separate a trustworthy OLS fit from a misleading one.</span> (1) <strong>Correct specification</strong> y = β₁ + β₂x + u; (2) <strong>mean-zero errors</strong> E[u|x] = 0; (3) <strong>homoskedasticity</strong> Var[u|x] = σ²ᵤ; (4) <strong>independence</strong> of errors across observations. Assumptions 1–2 are essential for unbiasedness; 3–4 affect variance and can be relaxed with robust standard errors.", es: "<span class=\"kc-title\">Cuatro supuestos separan un ajuste MCO confiable de uno engañoso.</span> (1) <strong>Especificación correcta</strong> y = β₁ + β₂x + u; (2) <strong>errores con media cero</strong> E[u|x] = 0; (3) <strong>homocedasticidad</strong> Var[u|x] = σ²ᵤ; (4) <strong>independencia</strong> de los errores entre observaciones. Los supuestos 1–2 son esenciales para el insesgamiento; 3–4 afectan la varianza y pueden relajarse con errores estándar robustos." },
  "widget.assumptions.motivation": { en: "OLS is trustworthy only when four background assumptions hold. Which ones <em>bend the line</em>, and which only bend the standard errors?", es: "MCO es confiable solo cuando se cumplen cuatro supuestos de fondo. ¿Cuáles <em>doblan la línea</em>, y cuáles solo doblan los errores estándar?" },
  "widget.assumptions.stat.bias": { en: "Bias (b₂ − β₂)", es: "Sesgo (b₂ − β₂)" },
  "widget.assumptions.stat.sampleb2": { en: "Sample b₂", es: "Muestra b₂" },
  "widget.assumptions.stat.se": { en: "se(b₂)", es: "ee(b₂)" },
  "widget.assumptions.stat.trueb2": { en: "True β₂", es: "β₂ verdadero" },
  "widget.assumptions.takeaway": { en: "<strong>Take-away:</strong> Assumptions 1–2 decide whether b₂ is centered on β₂; assumptions 3–4 decide how precise the SE reports are. <a href=\"../../book/_book/notebooks_quarto/ch06_The_Least_Squares_Estimator.html#properties-of-the-least-squares-estimator\" target=\"_blank\" rel=\"noopener\">Read §6.3 in the chapter →</a>", es: "<strong>Para recordar:</strong> Los supuestos 1–2 deciden si b₂ está centrado en β₂; los supuestos 3–4 deciden qué tan precisos son los EE reportados. <a href=\"../../book/_book/notebooks_quarto/ch06_The_Least_Squares_Estimator.html#properties-of-the-least-squares-estimator\" target=\"_blank\" rel=\"noopener\">Lee §6.3 en el capítulo →</a>" },
  "widget.assumptions.try": { en: "<li><strong>Select \"Mean-Zero\" and push severity to 100%.</strong> The sample line consistently misses the true line. <em>This is omitted-variable bias — the most dangerous violation because it shifts b₂ systematically away from β₂.</em></li>\n      <li><strong>Select \"Homosk.\" at 100%.</strong> The fitted line still tracks the true line well (b₂ ≈ 2), but the scatter fans out. <em>The slope is fine; only the reported se(b₂) becomes unreliable.</em></li>\n      <li><strong>Set \"All Correct\" and Resimulate several times.</strong> b₂ varies randomly around 2.0 with no drift. <em>Random around the truth, never systematic — that is the hallmark of an unbiased estimator.</em></li>", es: "<li><strong>Selecciona \"Media cero\" y empuja la severidad al 100%.</strong> La línea muestral falla sistemáticamente respecto a la línea verdadera. <em>Este es el sesgo por variables omitidas — la violación más peligrosa porque desplaza b₂ sistemáticamente lejos de β₂.</em></li>\n      <li><strong>Selecciona \"Homocedast.\" al 100%.</strong> La línea ajustada todavía sigue bien la línea verdadera (b₂ ≈ 2), pero la nube se abre. <em>La pendiente está bien; solo el ee(b₂) reportado se vuelve poco confiable.</em></li>\n      <li><strong>Establece \"Todo correcto\" y resimula varias veces.</strong> b₂ varía aleatoriamente alrededor de 2.0 sin deriva. <em>Aleatorio alrededor de la verdad, nunca sistemático — ese es el sello de un estimador insesgado.</em></li>" },
  "widget.conv.chart.hist.legend": { en: "b₂ estimates", es: "estimaciones de b₂" },
  "widget.conv.chart.hist.popLabel": { en: "Pop β₂", es: "β₂ pob." },
