  "widget.conv.chart.hover.all": { en: "%{text}<br>Capital=%{x:.0f}<br>Prod=%{y:.0f}<extra></extra>", es: "%{text}<br>Capital=%{x:.0f}<br>Prod=%{y:.0f}<extra></extra>" },
