  "widget.mc.chart.xaxis.intercept": { en: "b₁ estimates", es: "estimaciones de b₁" },
  "widget.mc.chart.xaxis.slope": { en: "b₂ estimates", es: "estimaciones de b₂" },
  "widget.mc.chart.yaxis": { en: "Density", es: "Densidad" },
  "widget.mc.ctrl.n.label": { en: "Sample size n", es: "Tamaño de muestra n" },
  "widget.mc.ctrl.nsim.label": { en: "Simulations", es: "Simulaciones" },
  "widget.mc.ctrl.param.intercept": { en: "Intercept (b₁)", es: "Intercepto (b₁)" },
